/**
 * The audit pipeline (`docs/verification/pipeline/`), held by the gate (from 2026-10-16, brief 11). The coverage area of
 * brief 09 extended the fold three times (its items 09.4 to 09.6), and until brief 11 nothing the gate ran held any of
 * them: the audit (`docs/verification/audit/*.json`) was regenerated by hand and checked by a `git diff` read once.
 *
 * Here the pipeline runs in its README's order in a copy of the folders it reads, and must make the committed audit and
 * the merge's inputs byte for byte. A hand edit of the audit, a script changed without the audit made again, or a result
 * changed without its fold each fails it. `resolve-titles.cjs`, the README's last step, isn't run: since brief 09's
 * journeys' follow-up it writes nothing, and it runs `tools/coverage.mjs`, whose `--check` the gate runs on its own (each
 * title the audit cites is a test in its file).
 *
 * Then what each fold was for, read from the copy's output so that a change to a script fails here and not only above:
 * - 09.4, remaining-09/ folded: every test a fold record adds reaches the row it names, under the record's round;
 * - 09.5, an area's tests mapped one by one (`byTest`): each reaches the rows its own map names and no other, where a row
 *   that already cites it (in its text or an earlier round) isn't given it again, as the fold's README says;
 * - 09.6, the journeys' follow-up: each `<field> (add)` and `settled` an area wrote is placed in its row once. The fold
 *   reads its own last output (`doc-fields.json`) as the field it adds to, so on the committed inputs an add it once
 *   placed stays placed whatever the script does now; it's taken out of a second copy first, and the fold must put it
 *   back, byte for byte.
 *
 * GUARD: the repository's own records, not a player's journey.
 */
import { execFileSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

/** What the five scripts read and write, relative to the repository's root. */
const COPIED = ['docs/verification/pipeline', 'docs/verification/scope', 'docs/verification/remaining', 'docs/verification/remaining-09', 'docs/verification/completion-2026-10-16', 'docs/verification/audit', 'tests'];
const INPUTS = 'docs/verification/pipeline/inputs';
const AUDIT = 'docs/verification/audit';
const MERGE_ARGS = ['evidence-results.json,evidence2-results.json,evidence3-results.json,evidence4-results.json,evidence5-results.json', 'mutations.json,mutations2-final.json,mutations3.json,mutations4-final.json', 'fixes.json', 'checks.json'];

type AfterTest = { file?: string; title?: string; round?: string };
type AuditRow = { id: string; after?: { tests?: AfterTest[] }; [field: string]: unknown };
type FoldRecord = { key: string; rows: { id: string; testsAdded?: { title: string }[] }[] };
type ByTest = { title: string; rows: string[] };

const files = (dir: string): string[] => readdirSync(dir).filter((f) => statSync(join(dir, f)).isFile()).sort();
const json = <T,>(path: string): T => JSON.parse(readFileSync(path, 'utf8')) as T;

const copies: string[] = [];
/** The folders copied, then `prepare` on the copy, then the pipeline in the README's order; the copy's root. */
function pipelineIn(prepare: (root: string) => void = () => {}): string {
  const root = mkdtempSync(join(tmpdir(), 'slate-pipeline-'));
  copies.push(root);
  for (const dir of COPIED) cpSync(dir, join(root, dir), { recursive: true });
  prepare(root);
  const run = (script: string, ...args: string[]) => execFileSync('node', [`../${script}`, ...args], { cwd: join(root, INPUTS), stdio: 'pipe' });
  run('scope-fold.cjs');
  run('remaining-fold.cjs');
  run('collect-checks.cjs');
  run('scope-prep.cjs');
  run('merge-review.cjs', ...MERGE_ARGS);
  return root;
}
/** Each file the pipeline writes that differs between a copy and the repository. */
function differing(root: string): string[] {
  const out: string[] = [];
  for (const dir of [AUDIT, INPUTS, `${INPUTS}/final-checks`]) {
    const mine = files(join(root, dir)), theirs = files(dir);
    for (const f of new Set([...mine, ...theirs])) if (!mine.includes(f) || !theirs.includes(f) || readFileSync(join(root, dir, f), 'utf8') !== readFileSync(join(dir, f), 'utf8')) out.push(`${dir}/${f}`);
  }
  return out;
}

let copy = '';
const audit = new Map<string, AuditRow>();
const testsOf = (row: AuditRow | undefined): AfterTest[] => row?.after?.tests ?? [];

beforeAll(() => {
  copy = pipelineIn();
  for (const f of files(join(copy, AUDIT))) for (const row of json<{ items: AuditRow[] }>(join(copy, AUDIT, f)).items) audit.set(row.id, row);
}, 60_000);

afterAll(() => {
  for (const root of copies) rmSync(root, { recursive: true, force: true });
});

/** Every `<field> (add)` (bar evidence, placed as a test) and `settled` the areas' results write, by row and field. */
function addsWritten(): { result: string; item: string; row: string; field: string; value: string }[] {
  const out: { result: string; item: string; row: string; field: string; value: string }[] = [];
  for (const dir of ['docs/verification/remaining', 'docs/verification/remaining-09']) {
    for (const f of files(dir).filter((x) => x.endsWith('-result.json'))) {
      const result = json<unknown>(join(dir, f));
      const items = (Array.isArray(result) ? result : (result as { items?: unknown[] }).items ?? []) as { id: string; rowText?: Record<string, unknown> }[];
      for (const item of items) {
        for (const [row, fields] of Object.entries(item.rowText ?? {})) {
          if (typeof fields !== 'object' || fields === null) continue;
          for (const [k, value] of Object.entries(fields as Record<string, string>)) {
            if ((k.endsWith(' (add)') && k !== 'evidence (add)') || k === 'settled') out.push({ result: f, item: item.id, row, field: k.replace(' (add)', ''), value });
          }
        }
      }
    }
  }
  return out;
}

describe('the audit pipeline, run in a copy', () => {
  it('GUARD: makes the committed audit and the merge’s inputs, byte for byte', () => {
    expect(differing(copy), 'not what the pipeline makes').toEqual([]);
    expect(files(join(copy, AUDIT))).toContain('money.json');
    expect(files(join(copy, INPUTS))).toContain('evidence5-results.json');
  });

  it('GUARD: coverage09.4, every test a fold record adds reaches the row it names, remaining-09’s results among them', () => {
    const records = json<FoldRecord[]>(join(copy, INPUTS, 'evidence5-results.json'));
    for (const key of ['remaining-09-banking', 'remaining-09-coverage', 'remaining-09-journeys', 'remaining-09-judge']) expect(records.some((r) => r.key === key), key).toBe(true);
    const renames = json<Record<string, string>>(join(copy, INPUTS, 'renames.json'));
    let placed = 0;
    for (const rec of records.filter((r) => r.key.startsWith('remaining-09-'))) {
      for (const r of rec.rows) {
        for (const t of r.testsAdded ?? []) {
          // A title renamed since is cited under its last name (renames.json), and only the `it` part is renamed.
          const last = t.title.split(' > ').map((p) => renames[p] ?? p).join(' > ');
          const there = testsOf(audit.get(r.id)).some((a) => a.round === rec.key && (a.title === t.title || a.title === last));
          expect(there, `${rec.key}: ‘${t.title.slice(0, 80)}’ isn’t on ${r.id}`).toBe(true);
          placed += 1;
        }
      }
    }
    expect(placed).toBeGreaterThan(100);
  });

  it('GUARD: coverage09.5, a test mapped by itself reaches the rows its own map names and no other', () => {
    const byTest = json<{ byTest: Record<string, ByTest[]> }>(join(copy, INPUTS, 'remaining-rows.json')).byTest;
    expect(Object.keys(byTest)).toEqual(expect.arrayContaining(['09-journeys']));
    let mapped = 0;
    for (const [key, entries] of Object.entries(byTest)) {
      const round = `remaining-${key}`;
      for (const e of entries) {
        const reached = [...audit.values()].filter((row) => testsOf(row).some((a) => a.round === round && (a.title ?? '').includes(e.title))).map((row) => row.id);
        for (const id of reached) expect(e.rows, `${round}: ‘${e.title.slice(0, 60)}’ reached ${id}, which its map doesn’t name`).toContain(id);
        for (const id of e.rows.filter((x) => !reached.includes(x))) {
          // Not given it again: the row already cites it, in its own text or an earlier round.
          const row = audit.get(id);
          expect(row, `${round}: its map names ${id}, which the audit hasn’t`).toBeDefined();
          const already = JSON.stringify({ ...row, after: undefined }).includes(e.title.slice(0, 40)) || testsOf(row).some((a) => a.round !== round && (a.title ?? '').includes(e.title));
          expect(already, `${round}: ‘${e.title.slice(0, 60)}’ never reached ${id}`).toBe(true);
        }
        mapped += 1;
      }
    }
    expect(mapped).toBeGreaterThan(30);
  });

  it('GUARD: coverage09.6, each field an area added to and each deferred row’s settled are placed in their rows once', () => {
    const adds = addsWritten();
    expect(adds.length).toBeGreaterThanOrEqual(8);
    // Taken out of a second copy's doc-fields.json: a field's adds from the first to its end, and a settled whole.
    const stripped = pipelineIn((root) => {
      const path = join(root, INPUTS, 'doc-fields.json');
      const doc = json<Record<string, Record<string, string>>>(path);
      for (const a of adds) {
        const fields = doc[a.row];
        expect(fields?.[a.field], `${a.result} ${a.item}: ${a.row}’s ${a.field} isn’t in doc-fields.json`).toBeDefined();
        if (a.field === 'settled') { delete fields![a.field]; continue; }
        const at = fields![a.field]!.indexOf(a.value.slice(0, 60));
        expect(at, `${a.result} ${a.item}: ${a.row}’s ${a.field} doesn’t hold the add`).toBeGreaterThan(0);
        fields![a.field] = fields![a.field]!.slice(0, at).replace(/[;.]?\s*$/, '');
      }
      writeFileSync(path, JSON.stringify(doc, null, 1));
    });
    expect(differing(stripped), 'the fold didn’t put back what it places').toEqual([]);
    const rows = new Map<string, AuditRow>();
    for (const f of files(join(stripped, AUDIT))) for (const row of json<{ items: AuditRow[] }>(join(stripped, AUDIT, f)).items) rows.set(row.id, row);
    for (const a of adds) expect(String(rows.get(a.row)?.[a.field] ?? '').split(a.value.slice(0, 60)).length - 1, `${a.result} ${a.item}: ${a.row}’s ${a.field}`).toBe(1);
  }, 60_000);
});
